<?php
require_once __DIR__ . '/../helpers.php'; require_once __DIR__ . '/../config/database.php'; require_login();
$type=$_GET['type']??'';$q=trim((string)($_GET['q']??''));$where=[];$params=[];if(in_array($type,['in','out'],true)){$where[]='t.type=?';$params[]=$type;}if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR u.username LIKE ?)';array_push($params,"%$q%","%$q%","%$q%");}$w=$where?' WHERE '.implode(' AND ',$where):'';$s=$pdo->prepare('SELECT t.*,p.name product_name,p.sku,u.username FROM stock_transactions t JOIN products p ON p.id=t.product_id JOIN users u ON u.id=t.user_id'.$w.' ORDER BY t.id DESC LIMIT 300');$s->execute($params);$rows=$s->fetchAll();
layout_start('Riwayat Transaksi');echo '<div class="card"><form class="inline" method="get"><div><label>Cari produk/SKU/pengguna</label><input name="q" value="'.e($q).'"></div><div><label>Jenis</label><select name="type"><option value="">Semua</option><option value="in" '.($type==='in'?'selected':'').'>Masuk</option><option value="out" '.($type==='out'?'selected':'').'>Keluar</option></select></div><div><button>Filter</button> <a class="btn secondary" href="history.php">Reset</a></div></form></div><div class="card table-wrap"><table><tr><th>Tanggal</th><th>SKU</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Pengguna</th><th>Catatan</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['sku']).'</td><td>'.e($r['product_name']).'</td><td>'.($r['type']==='in'?'Masuk':'Keluar').'</td><td>'.(int)$r['quantity'].'</td><td>'.e($r['username']).'</td><td>'.e($r['note']).'</td></tr>';if(!$rows)echo '<tr><td colspan="7">Belum ada riwayat.</td></tr>';echo '</table><p class="muted">Menampilkan maksimal 300 transaksi terbaru.</p></div>';layout_end();
